package vn.iotstar;
import org.junit.jupiter.api.*; import org.springframework.beans.factory.annotation.*; import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.http.MediaType; import org.springframework.mock.web.MockMultipartFile; import org.springframework.test.context.ActiveProfiles; import org.springframework.test.web.servlet.MockMvc; import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*; import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest @AutoConfigureMockMvc @ActiveProfiles("test") class CategoryApiControllerTest { @Autowired MockMvc mvc;
 @Test void categoryCrudAndValidation() throws Exception { mvc.perform(post("/api/category/addCategory").param("categoryName","Điện tử").contentType(MediaType.MULTIPART_FORM_DATA)).andExpect(status().isCreated()).andExpect(jsonPath("$.body.categoryName").value("Điện tử")); mvc.perform(post("/api/category/addCategory").param("categoryName","điện tử").contentType(MediaType.MULTIPART_FORM_DATA)).andExpect(status().isConflict()); mvc.perform(post("/api/category/addCategory").param("categoryName"," ").contentType(MediaType.MULTIPART_FORM_DATA)).andExpect(status().isBadRequest()); mvc.perform(get("/api/category")).andExpect(status().isOk()).andExpect(jsonPath("$.body.length()").value(1)); mvc.perform(put("/api/category/updateCategory").param("categoryId","1").param("categoryName","Gia dụng").contentType(MediaType.MULTIPART_FORM_DATA)).andExpect(status().isOk()).andExpect(jsonPath("$.body.categoryName").value("Gia dụng")); mvc.perform(delete("/api/category/deleteCategory").param("categoryId","1")).andExpect(status().isOk()); mvc.perform(post("/api/category/getCategory").param("id","1")).andExpect(status().isNotFound()); }
 @Test void rejectsBadUpload() throws Exception { MockMultipartFile f=new MockMultipartFile("icon","x.txt","text/plain","x".getBytes()); mvc.perform(multipart("/api/category/addCategory").file(f).param("categoryName","Sách")).andExpect(status().isBadRequest()); }
 @Test void openApiIsAvailable() throws Exception { mvc.perform(get("/v3/api-docs")).andExpect(status().isOk()).andExpect(jsonPath("$.info.title").value("Product Category REST API")).andExpect(jsonPath("$.paths['/api/category/addCategory']").exists()); }}
